if (numberOfChecks <= 0) {
    return false;
}

// Define CGAL types based on repository patterns
typedef typename Tree::Kernel K;
typedef typename K::Point_3 CGALPoint;
typedef typename K::Segment_3 CGALSegment;

// Convert input point to CGAL point
CGALPoint cgalPoint(p.x(), p.y(), p.z());

// Random number generation
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<> dis(-1.0, 1.0);

int totalIntersections = 0;

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction
    double dx = dis(gen);
    double dy = dis(gen);
    double dz = dis(gen);

    // Normalize the direction to avoid bias
    double length = std::sqrt(dx * dx + dy * dy + dz * dz);
    if (length == 0.0) {
        continue; // Avoid division by zero
    }
    dx /= length;
    dy /= length;
    dz /= length;

    // Create a far point in the random direction
    CGALPoint farPoint(cgalPoint.x() + dx * 1e6, 
                       cgalPoint.y() + dy * 1e6, 
                       cgalPoint.z() + dz * 1e6);

    // Create a segment (ray) from the point to the far point
    CGALSegment ray(cgalPoint, farPoint);

    // Query the AABB tree for intersections
    std::list<typename Tree::Primitive_id> intersections;
    tree.all_intersected_primitives(ray, std::back_inserter(intersections));

    // Count intersections
    totalIntersections += intersections.size();
}

// If the total number of intersections is odd, the point is inside
return (totalIntersections % 2) == 1;

